27. // e2eCrudDeploymentModel mirrors the (unexported) provider.deploymentModel tfsdk
28. // shape so this external package can build tfsdk.Plan/State through the REAL resource
29. // schema by tfsdk tag (the framework maps by tag, not Go type identity). It includes
30. // the timeouts block field so a Set against the real schema (which declares that
31. // block) round-trips faithfully (DESIGN §5.2).
32. type e2eCrudDeploymentModel struct {
33. 	ID              types.String   `tfsdk:"id"`
34. 	Name            types.String   `tfsdk:"name"`
35. 	Spec            types.String   `tfsdk:"spec"`
36. 	SpecFile        types.String   `tfsdk:"spec_file"`
37. 	Variables       types.Map      `tfsdk:"variables"`
38. 	VersionOverride types.String   `tfsdk:"version_override"`
39. 	DestroyMode     types.String   `tfsdk:"destroy_mode"`
40. 	SpecHash        types.String   `tfsdk:"spec_hash"`
41. 	ResolvedSpec    types.String   `tfsdk:"resolved_spec"`
42. 	DeployedVersion types.String   `tfsdk:"deployed_version"`
43. 	PreviousVersion types.String   `tfsdk:"previous_version"`
44. 	Hosts           types.List     `tfsdk:"hosts"`
45. 	ReleasePath     types.String   `tfsdk:"release_path"`
46. 	ServiceStatus   types.String   `tfsdk:"service_status"`
47. 	Timeouts        timeouts.Value `tfsdk:"timeouts"`
48. }
