189. type crudState struct {
190. 	baselineYAML string // becomes the persisted resolved_spec snapshot (prior)
191. 	modifiedYAML string // becomes the new plan's inline spec
192. 
193. 	modifyResp *resource.ModifyPlanResponse
194. 
195. 	createSummary string
196. 	createErrored bool
197. 
198. 	idOriginal  string
199. 	idReordered string
200. 	idExpected  string
201. 
202. 	tCreate, tUpdate, tDelete time.Duration
203. 
204. 	importErrored bool
205. 	importDetail  string
206. }
207. 
208. // runPlan drives the REAL DeploymentResource.ModifyPlan with a prior state carrying
209. // the baseline deployment (as a verbatim inline spec — the "verified" legacy prior
210. // that priorFromState reconstructs faithfully) and a plan carrying the modified inline
211. // spec, so the immutableKey comparison runs against the real resolved specs.
212. func runPlan(baselineYAML, modifiedYAML string) (*resource.ModifyPlanResponse, error) {
213. 	ctx := context.Background()
214. 	sr := resource.SchemaResponse{}
215. 	(&provider.DeploymentResource{}).Schema(ctx, resource.SchemaRequest{}, &sr)
216. 
217. 	plan := &e2eCrudDeploymentModel{
218. 		Spec:         types.StringValue(modifiedYAML),
219. 		SpecFile:     types.StringNull(),
220. 		Variables:    types.MapNull(types.StringType),
221. 		ResolvedSpec: types.StringNull(),
222. 		SpecHash:     types.StringNull(),
223. 		Hosts:        types.ListNull(types.StringType),
224. 		Timeouts:     e2eNullTimeouts(),
225. 	}
226. 	state := &e2eCrudDeploymentModel{
227. 		Spec:         types.StringValue(baselineYAML),
228. 		SpecFile:     types.StringNull(),
229. 		Variables:    types.MapNull(types.StringType),
230. 		ResolvedSpec: types.StringNull(),
231. 		SpecHash:     types.StringValue("prior-hash"),
232. 		Hosts:        types.ListNull(types.StringType),
233. 		Timeouts:     e2eNullTimeouts(),
234. 	}
235. 
236. 	p := tfsdk.Plan{Schema: sr.Schema}
237. 	if d := p.Set(ctx, plan); d.HasError() {
238. 		return nil, fmt.Errorf("build plan: %v", d)
239. 	}
240. 	st := tfsdk.State{Schema: sr.Schema}
241. 	if d := st.Set(ctx, state); d.HasError() {
242. 		return nil, fmt.Errorf("build state: %v", d)
243. 	}
244. 	resp := &resource.ModifyPlanResponse{Plan: p}
245. 	(&provider.DeploymentResource{}).ModifyPlan(ctx, resource.ModifyPlanRequest{
246. 		Plan:   p,
247. 		State:  st,
248. 		Config: tfsdk.Config{Schema: sr.Schema, Raw: p.Raw},
249. 	}, resp)
250. 	return resp, nil
251. }
