253. // --- immutable-path / reorder steps -------------------------------------------
254. 
255. func (s *crudState) givenPriorSnapshot() error { return nil }
256. 
257. func (s *crudState) givenPlanChangesImmutableField(field string) error {
258. 	switch field {
259. 	case "pattern.type":
260. 		s.baselineYAML = e2eWSSpecYAMLHost("1.0.0", "lab-01")
261. 		s.modifiedYAML = e2eDotnetSpecYAML("lab-01")
262. 	case "service_name":
263. 		s.baselineYAML = e2eWSSpecServiceYAML("SampleSvc", "lab-01")
264. 		s.modifiedYAML = e2eWSSpecServiceYAML("OtherSvc", "lab-01")
265. 	case "target.hosts":
266. 		s.baselineYAML = e2eWSSpecYAMLHost("1.0.0", "lab-01")
267. 		s.modifiedYAML = e2eWSSpecYAMLHost("1.0.0", "lab-02")
268. 	case "target.os":
269. 		s.baselineYAML = e2eConsoleSpecYAML("windows", "lab-01")
270. 		s.modifiedYAML = e2eConsoleSpecYAML("linux", "lab-01")
271. 	default:
272. 		return fmt.Errorf("unknown immutable field %q", field)
273. 	}
274. 	return nil
275. }
