287. func (s *crudState) whenPlanComputed() error {
288. 	resp, err := runPlan(s.baselineYAML, s.modifiedYAML)
289. 	if err != nil {
290. 		return err
291. 	}
292. 	if resp.Diagnostics.HasError() {
293. 		return fmt.Errorf("plan computation errored: %v", resp.Diagnostics.Errors())
294. 	}
295. 	s.modifyResp = resp
296. 	return nil
297. }
298. 
299. func (s *crudState) thenReplaceForced() error {
300. 	if s.modifyResp == nil {
301. 		return fmt.Errorf("plan was not computed")
302. 	}
303. 	if len(s.modifyResp.RequiresReplace) == 0 {
304. 		return fmt.Errorf("expected the immutable-path change to force RequiresReplace, but it did not")
305. 	}
306. 	return nil
307. }
308. 
309. func (s *crudState) thenReplaceDoesNotFire() error {
310. 	if s.modifyResp == nil {
311. 		return fmt.Errorf("plan was not computed")
312. 	}
313. 	if len(s.modifyResp.RequiresReplace) != 0 {
314. 		return fmt.Errorf("host reorder must NOT force replacement, got RequiresReplace=%v", s.modifyResp.RequiresReplace)
315. 	}
316. 	return nil
317. }
