331. func (s *crudState) whenCreateSurfacesFailure() error {
332. 	ctx := context.Background()
333. 	r := provider.NewDeploymentResourceWithConnectError()
334. 	sr := resource.SchemaResponse{}
335. 	r.Schema(ctx, resource.SchemaRequest{}, &sr)
336. 
337. 	plan := &e2eCrudDeploymentModel{
338. 		Spec:         types.StringValue(e2eWSSpecYAMLHost("1.0.0", "lab-01")),
339. 		SpecFile:     types.StringNull(),
340. 		Variables:    types.MapNull(types.StringType),
341. 		ResolvedSpec: types.StringNull(),
342. 		SpecHash:     types.StringNull(),
343. 		Hosts:        types.ListNull(types.StringType),
344. 		Timeouts:     e2eNullTimeouts(),
345. 	}
346. 	p := tfsdk.Plan{Schema: sr.Schema}
347. 	if d := p.Set(ctx, plan); d.HasError() {
348. 		return fmt.Errorf("build plan: %v", d)
349. 	}
350. 	resp := &resource.CreateResponse{State: tfsdk.State{Schema: sr.Schema}}
351. 	r.Create(ctx, resource.CreateRequest{Plan: p}, resp)
352. 	s.createErrored = resp.Diagnostics.HasError()
353. 	if s.createErrored {
354. 		s.createSummary = resp.Diagnostics.Errors()[0].Summary()
355. 	}
356. 	return nil
357. }
358. 
359. func (s *crudState) thenSummaryBeginsWith(prefix string) error {
360. 	if !s.createErrored {
361. 		return fmt.Errorf("Create must surface the engine deploy failure")
362. 	}
363. 	if !strings.HasPrefix(s.createSummary, prefix) {
364. 		return fmt.Errorf("deploy failure Summary must begin with %q, got %q", prefix, s.createSummary)
365. 	}
366. 	return nil
367. }
