419. func (s *crudState) thenTimeoutDefaults() error {
420. 	if s.tCreate != 30*time.Minute {
421. 		return fmt.Errorf("create default = %s, want 30m", s.tCreate)
422. 	}
423. 	if s.tUpdate != 30*time.Minute {
424. 		return fmt.Errorf("update default = %s, want 30m", s.tUpdate)
425. 	}
426. 	if s.tDelete != 15*time.Minute {
427. 		return fmt.Errorf("delete default = %s, want 15m", s.tDelete)
428. 	}
429. 	return nil
430. }
