436. func (s *crudState) whenImportInvoked() error {
437. 	r := &provider.DeploymentResource{}
438. 	resp := &resource.ImportStateResponse{}
439. 	r.ImportState(context.Background(), resource.ImportStateRequest{ID: "anything"}, resp)
440. 	s.importErrored = resp.Diagnostics.HasError()
441. 	if s.importErrored {
442. 		s.importDetail = resp.Diagnostics.Errors()[0].Detail()
443. 	}
444. 	return nil
