447. func (s *crudState) thenImportError(msg string) error {
448. 	if !s.importErrored {
449. 		return fmt.Errorf("ImportState must surface an error")
450. 	}
451. 	if s.importDetail != msg {
452. 		return fmt.Errorf("import error message = %q, want the pinned %q", s.importDetail, msg)
453. 	}
454. 	return nil
455. }
