457. func InitializeScenario_terraform_provider_surface_deployment_resource_crud_and_plan_modifiers(ctx *godog.ScenarioContext) {
458. 	st := &crudState{}
459. 	ctx.Before(func(ctx context.Context, sc *godog.Scenario) (context.Context, error) {
460. 		*st = crudState{}
461. 		// Specs reference password_env: LABDEPLOY_PASSWORD; set it so parse/validate succeed.
462. 		if err := os.Setenv("LABDEPLOY_PASSWORD", "pw"); err != nil {
463. 			return ctx, err
464. 		}
465. 		return ctx, nil
466. 	})
467. 
468. 	ctx.Step(`^a prior deployment snapshot in state$`, st.givenPriorSnapshot)
469. 	ctx.Step(`^a plan that changes only the immutable field "([^"]*)"$`, st.givenPlanChangesImmutableField)
470. 	ctx.Step(`^a prior deployment snapshot with hosts "([^"]*)"$`, st.givenPriorSnapshotWithHosts)
471. 	ctx.Step(`^a plan with the same hosts reordered to "([^"]*)" and no other change$`, st.givenPlanReorderedTo)
472. 	ctx.Step(`^the deployment plan is computed$`, st.whenPlanComputed)
473. 	ctx.Step(`^the change forces RequiresReplace$`, st.thenReplaceForced)
474. 	ctx.Step(`^RequiresReplace does not fire$`, st.thenReplaceDoesNotFire)
475. 
476. 	ctx.Step(`^a deployment whose engine preflight fails with the ERR_CONNECT taxonomy code$`, st.givenEnginePreflightFails)
477. 	ctx.Step(`^Create surfaces the failure$`, st.whenCreateSurfacesFailure)
478. 	ctx.Step(`^the diagnostic Summary begins with "([^"]*)"$`, st.thenSummaryBeginsWith)
479. 
480. 	ctx.Step(`^a spec with name "([^"]*)" and hosts "([^"]*)"$`, st.givenSpecNameHosts)
481. 	ctx.Step(`^the deployment id is computed$`, st.whenIDComputed)
482. 	ctx.Step(`^it equals the sha1\(sorted\(hosts\)\+"/"\+name\)\[0:12\] \+ ":" \+ name formula$`, st.thenIDMatchesFormula)
483. 	ctx.Step(`^it is byte-identical when the same hosts are supplied in a different order$`, st.thenIDByteIdenticalReordered)
484. 
485. 	ctx.Step(`^a deployment resource config with no explicit timeouts$`, st.givenConfigNoTimeouts)
486. 	ctx.Step(`^the resource timeout defaults are read$`, st.whenTimeoutDefaultsRead)
487. 	ctx.Step(`^create and update default to 30m and delete defaults to 15m$`, st.thenTimeoutDefaults)
488. 
489. 	ctx.Step(`^the labdeploy_deployment resource$`, st.givenDeploymentResource)
490. 	ctx.Step(`^terraform import is invoked on it$`, st.whenImportInvoked)
491. 	ctx.Step(`^the error is "([^"]*)"$`, st.thenImportError)
492. }
