175. func (e *Engine) deploySingle(ctx context.Context, s *spec.Deployment) (*Status, error) {
176. 	host := strings.ToLower(s.Target.Hosts[0])
177. 	sl := newStepLogger(s, host)
178. 	vstart := time.Now()
179. 	t, err := e.NewTransport(&s.Target, host)
180. 	if err != nil {
181. 		sl.emit(ctx, "VALIDATE", vstart)
182. 		return nil, coded("ERR_SPEC_INVALID", host, "VALIDATE", err)
183. 	}
184. 	pat, verr := pattern.For(s.Pattern.Type)
185. 	sl.emit(ctx, "VALIDATE", vstart)
186. 	if verr != nil {
187. 		return nil, coded("ERR_UNSUPPORTED", host, "VALIDATE", verr)
188. 	}
189. 	cstart := time.Now()
190. 	if err := t.Connect(ctx); err != nil {
191. 		sl.emit(ctx, "CONNECT", cstart)
192. 		return nil, wrapTransportErr(err, host, "CONNECT")
193. 	}
194. 	sl.emit(ctx, "CONNECT", cstart)
195. 	defer t.Close()
196. 
197. 	p := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, s.Artifact.Version)
198. 	rc := releaseCtx(s, p)
199. 
200. 	if err := sl.timed(ctx, "PREFLIGHT", func() error { return e.preflight(ctx, t, s, p, pat, rc) }); err != nil {
201. 		return nil, err
202. 	}
203. 
204. 	lstart := time.Now()
205. 	lk, warn, err := AcquireLock(ctx, t, p, lockOwner(), "deploy", s.Strategy.EffectiveLockTimeout())
206. 	sl.emit(ctx, "LOCK", lstart)
207. 	if err != nil {
208. 		return nil, err
209. 	}
210. 	if warn != "" {
211. 		e.warnf("%s", warn)
212. 	}
213. 	defer func() {
214. 		rctx, cancel := lockCleanupContext(ctx)
215. 		defer cancel()
216. 		ustart := time.Now()
217. 		if rerr := ReleaseLock(rctx, lk); rerr != nil {
218. 			e.warnf("lock release failed on %s: %v", host, rerr)
219. 		}
220. 		sl.emit(ctx, "UNLOCK", ustart)
221. 	}()
222. 
223. 	m, err := ReadManifest(ctx, t, p)
224. 	if err != nil {
225. 		return nil, coded("ERR_CONNECT", host, "PREFLIGHT", err)
226. 	}
227. 
228. 	// Docker never uses staging/junction (DESIGN §9.6).
229. 	if s.Pattern.Type == spec.PatternDockerCont {
230. 		return e.deployDocker(ctx, sl, t, s, p, pat.(*pattern.DockerContainer), rc, m)
231. 	}
232. 
233. 	// Idempotency short-circuit (DESIGN §10.1 step 2).
234. 	if m != nil && m.CurrentVersion == s.Artifact.Version && m.ArtifactChecksum == s.Artifact.Checksum {
235. 		st, serr := pat.Status(ctx, t, rc)

